-- Generated by pipeline/flink/generate.ts from shared/queries.ts. Don't edit by hand.
-- All Tideline queries as one Flink job (one source read, six results).

EXECUTE STATEMENT SET
BEGIN

-- Changes per 10 seconds, by project
INSERT INTO tideline_pulse
  SELECT window_start, window_end,
    CASE
      WHEN wiki = 'wikidatawiki' THEN 'Wikidata'
      WHEN wiki = 'commonswiki' THEN 'Commons'
      WHEN wiki = 'enwiki' THEN 'English Wikipedia'
      WHEN server_name LIKE '%.wikipedia.org' THEN 'Other Wikipedias'
      ELSE 'Other projects'
    END AS project,
    COUNT(*) AS changes
  FROM TABLE(
    TUMBLE(TABLE recentchange, DESCRIPTOR(event_time), INTERVAL '10' SECOND))
  GROUP BY window_start, window_end,
    CASE
      WHEN wiki = 'wikidatawiki' THEN 'Wikidata'
      WHEN wiki = 'commonswiki' THEN 'Commons'
      WHEN wiki = 'enwiki' THEN 'English Wikipedia'
      WHEN server_name LIKE '%.wikipedia.org' THEN 'Other Wikipedias'
      ELSE 'Other projects'
    END;

-- People and bots
INSERT INTO tideline_editors
  SELECT window_start, window_end,
    COUNT(*) FILTER (WHERE NOT is_bot) AS by_people,
    COUNT(*) FILTER (WHERE is_bot) AS by_bots,
    COUNT(DISTINCT user_name) AS accounts
  FROM TABLE(
    TUMBLE(TABLE recentchange, DESCRIPTOR(event_time), INTERVAL '10' SECOND))
  GROUP BY window_start, window_end;

-- Trending articles
INSERT INTO tideline_trending
  SELECT *
  FROM (
    SELECT *,
      ROW_NUMBER() OVER (
        PARTITION BY window_start, window_end
        ORDER BY edits DESC, editors DESC, title, server_name) AS rownum
    FROM (
      SELECT window_start, window_end, server_name, title,
        COUNT(*) AS edits,
        COUNT(DISTINCT user_name) AS editors,
        SUM(delta) AS net_bytes
      FROM TABLE(
        HOP(TABLE recentchange, DESCRIPTOR(event_time),
            INTERVAL '1' MINUTE, INTERVAL '10' MINUTES))
      WHERE ns = 0 AND NOT is_bot
        AND change_type IN ('edit', 'new')
        AND server_name LIKE '%.wikipedia.org'
      GROUP BY window_start, window_end, server_name, title
    )
  )
  WHERE rownum <= 10;

-- New articles
INSERT INTO tideline_new_pages
  SELECT event_time, server_name, title, user_name, len_new
  FROM recentchange
  WHERE change_type = 'new' AND ns = 0 AND NOT is_bot;

-- Running totals per wiki (changelog)
INSERT INTO tideline_wiki_totals
  SELECT wiki,
    COUNT(*) AS changes,
    COUNT(*) FILTER (WHERE is_bot) AS bot_changes,
    MAX(event_time) AS last_change
  FROM recentchange
  GROUP BY wiki
  HAVING COUNT(*) >= 20;

-- Edit wars: three reverts in a row on one page by at least two people within 15 minutes
INSERT INTO tideline_edit_wars
  SELECT wiki, title, first_revert, third_revert, users
  FROM recentchange
  MATCH_RECOGNIZE (
    PARTITION BY wiki, title
    ORDER BY event_time
    MEASURES
      R1.event_time AS first_revert,
      R3.event_time AS third_revert,
      CONCAT(R1.user_name, ', ', R2.user_name, ', ', R3.user_name) AS users
    ONE ROW PER MATCH
    AFTER MATCH SKIP PAST LAST ROW
    PATTERN (R1 O1*? R2 O2*? R3) WITHIN INTERVAL '15' MINUTE
    DEFINE
      R1 AS REGEXP(R1.edit_comment, '(?iu)(undid revision|undo revision|reverted edits? by|reverted to revision|restored revision|^rvv?\b|^revert|rückgängig|annulation|revertid|annullat|отмена правки|отменены правки|取り消し|ロールバック)'),
      R2 AS REGEXP(R2.edit_comment, '(?iu)(undid revision|undo revision|reverted edits? by|reverted to revision|restored revision|^rvv?\b|^revert|rückgängig|annulation|revertid|annullat|отмена правки|отменены правки|取り消し|ロールバック)'),
      R3 AS REGEXP(R3.edit_comment, '(?iu)(undid revision|undo revision|reverted edits? by|reverted to revision|restored revision|^rvv?\b|^revert|rückgängig|annulation|revertid|annullat|отмена правки|отменены правки|取り消し|ロールバック)')
        AND (R2.user_name <> R1.user_name OR R3.user_name <> R1.user_name),
      O1 AS NOT REGEXP(O1.edit_comment, '(?iu)(undid revision|undo revision|reverted edits? by|reverted to revision|restored revision|^rvv?\b|^revert|rückgängig|annulation|revertid|annullat|отмена правки|отменены правки|取り消し|ロールバック)'),
      O2 AS NOT REGEXP(O2.edit_comment, '(?iu)(undid revision|undo revision|reverted edits? by|reverted to revision|restored revision|^rvv?\b|^revert|rückgängig|annulation|revertid|annullat|отмена правки|отменены правки|取り消し|ロールバック)')
  );

END;
